// TitleName returns the display name for a title id. Id 0 means
// the character has no title equipped.
func TitleName(id int) string {
	if id == 0 {
		return ""
	}
	if n, ok := titleNames[id]; ok {
		return n
	}
	return fmt.Sprintf("Title #%d", id)
}
